#pragma once
// Embedded offline web files and the generic resource provider of the WebView editor.
// Depends only on JUCE types (no WebView2); the table is generated by webshell/GenerateEmbedded.cmake from a
// directory, so a later task only switches which directory is embedded.
#include <juce_gui_extra/juce_gui_extra.h>

#include <cstddef>
#include <optional>

namespace verbweb {

struct EmbeddedFile {
    const char* path;  // relative, '/'-separated, e.g. "juce/index.js"
    const unsigned char* data;
    std::size_t size;
};

// Implemented by the generated source (one per embedded directory).
const EmbeddedFile* embeddedFileTable(std::size_t& count);

struct FileView {
    const unsigned char* data = nullptr;
    std::size_t size = 0;
    juce::String mime;
};

// MIME type from the file extension (explicit allowlist; unknown -> application/octet-stream).
juce::String mimeTypeFor(const juce::String& path);

// Normalises a request path ("/", "/a/b.js?x=1#y", "%2e" escapes) to a relative embedded path.
// "/" and "" map to "index.html". Returns an empty string for anything unsafe (".." segments, backslashes,
// colons, NUL, empty segments, trailing slash on a non-root path).
juce::String normaliseRequestPath(const juce::String& url);

class ResourceTable {
public:
    ResourceTable();                                              // uses the generated table
    ResourceTable(const EmbeddedFile* files, std::size_t count);  // explicit table (tests)
    std::optional<FileView> find(const juce::String& requestPath) const;  // nullopt = 404
    std::size_t size() const { return count; }

private:
    const EmbeddedFile* files;
    std::size_t count;
};

// The JUCE resource provider over `table` (must outlive the browser). JUCE can only answer 200, so a missing path
// is answered by a small text/plain "404 Not Found" body: an empty answer would let the request fall through to the
// real network, and nothing may ever be fetched from a network.
juce::WebBrowserComponent::ResourceProvider makeResourceProvider(const ResourceTable& table);

// Navigation policy: only the resource provider origin (and about:blank) may be loaded.
bool isNavigationAllowed(const juce::String& url);

}  // namespace verbweb
